 * Pure business rules, no framework dependencies.
 */
export class User {
  private constructor(
    private readonly _id: string,
    private _email: Email,
    private _roles: string[] = ['user']
  ) {}

  /**
   * Factory method to create new User.
   * @param id - Unique identifier
   * @param email - Validated email value object
   */
  static create(id: string, email: Email): User {
    return new User(id, email);
  }

  // Getters (encapsulation)
  get id(): string { return this._id; }
  get email(): Email { return this._email; }
  get roles(): readonly string[] { return Object.freeze([...this._roles]); }

  // Business logic methods
  assignRole(role: string): void {
    if (this._roles.includes(role)) {
      throw new BusinessError('ROLE_EXISTS', `User already has role: ${role}`);
    }
    this._roles.push(role);
  }
}
```

### Use-Case Structure (Application Layer)
```typescript
/**
 * CreateUserUseCase
 * Orchestrates user creation: validate, persist, notify.
 * Returns Result<T,E> for expected business failures.
 */
@Injectable()
export class CreateUserUseCase {
  constructor(
    @Inject('UserRepository') private readonly userRepo: UserRepository,
    private readonly hasher: PasswordHasher,
    private readonly notifier: NotificationService
  ) {}

  async execute(dto: CreateUserDto): Promise<Result<User, AppError>> {
    // Check for duplicate (expected failure → return err)
    const existing = await this.userRepo.findByEmail(dto.email);
    if (existing) {
      return err(new DuplicateUserError(dto.email));
    }

    // Domain creation
    const email = Email.create(dto.email);
    const hashedPassword = await this.hasher.hash(dto.password);
    const user = User.create(dto.id, email);

    // Persist via port
    await this.userRepo.save(user);

    // Side effect via port
    await this.notifier.send(dto.email, 'Welcome', 'Account created');

    return ok(user);
  }
}
```

