# Advanced Patterns — Complete Catalog

## GoF (Gang of Four) Patterns

### Creational Patterns

#### Abstract Factory
```typescript
export interface AbstractFactory {
  createProductA(): ProductA;
  createProductB(): ProductB;
}

export class ConcreteFactory1 implements AbstractFactory {
  createProductA(): ProductA { return new ProductA1(); }
  createProductB(): ProductB { return new ProductB1(); }
}
```

#### Builder
```typescript
export class QueryBuilder {
  private selectFields: string[] = [];
  private fromTable: string = '';
  private whereClauses: string[] = [];

  select(...fields: string[]): this {
    this.selectFields = fields;
    return this;
  }

  from(table: string): this {
    this.fromTable = table;
    return this;
  }

  where(clause: string): this {
    this.whereClauses.push(clause);
    return this;
  }

  build(): string {
    return `SELECT ${this.selectFields.join(', ')} FROM ${this.fromTable}${this.whereClauses.length ? ' WHERE ' + this.whereClauses.join(' AND ') : ''}`;
  }
}

// Usage
const query = new QueryBuilder()
  .select('id', 'email')
  .from('users')
  .where('active = true')
  .build();
```

#### Prototype
```typescript
export interface Prototype<T> {
  clone(): T;
}

export class UserProfile implements Prototype<UserProfile> {
  constructor(
    public name: string,
    public email: string,
    public preferences: Record<string, unknown>
  ) {}

  clone(): UserProfile {
    return new UserProfile(
      this.name,
      this.email,
      { ...this.preferences }
    );
  }
}
```

#### Singleton (Use with Caution)
```typescript
export class AppConfig {
  private static instance: AppConfig;
  private constructor(public readonly settings: Record<string, unknown>) {}

  static getInstance(): AppConfig {
    if (!AppConfig.instance) {
      AppConfig.instance = new AppConfig({});
    }
    return AppConfig.instance;
  }
}
// ⚠️ Avoid in favor of DI container
```

