### Structural Patterns

#### Adapter (Already in applying-design-patterns — extended)
```typescript
// Object Adapter (uses composition)
export class StripePaymentAdapter implements PaymentService {
  constructor(private stripe: Stripe) {}
  async charge(amount: number): Promise<void> {
    await this.stripe.charges.create({ amount, currency: 'USD' });
  }
}

// Class Adapter (uses inheritance — TypeScript limitation with interfaces)
export class StripePaymentAdapter extends Stripe implements PaymentService {
  async charge(amount: number): Promise<void> {
    await this.charges.create({ amount, currency: 'USD' });
  }
}
```

#### Bridge
```typescript
// Abstraction
export abstract class RemoteControl {
  constructor(protected device: Device) {}
  abstract turnOn(): void;
  abstract turnOff(): void;
}

// Refined Abstraction
export class AdvancedRemote extends RemoteControl {
  turnOn(): void { this.device.enable(); }
  turnOff(): void { this.device.disable(); }
  setVolume(level: number): void { this.device.setVolume(level); }
}

// Implementor
export interface Device {
  enable(): void;
  disable(): void;
  setVolume(level: number): void;
}
```

#### Composite
```typescript
export interface Component {
  operation(): string;
}

export class Leaf implements Component {
  constructor(private name: string) {}
  operation(): string { return `Leaf: ${this.name}`; }
}

export class Composite implements Component {
  private children: Component[] = [];
  constructor(private name: string) {}

  add(component: Component): void {
    this.children.push(component);
  }

  operation(): string {
    return `Composite: ${this.name}\n${this.children.map(c => c.operation()).join('\n')}`;
  }
}
```

#### Facade (Extended)
```typescript
// Complex subsystem
export class CPU { start(): void { console.log('CPU started'); } }
export class Memory { load(): void { console.log('Memory loaded'); } }
export class HardDrive { read(): void { console.log('HD read'); } }

// Facade
export class ComputerFacade {
  constructor(
    private cpu: CPU,
    private memory: Memory,
    private hardDrive: HardDrive
  ) {}

  start(): void {
    this.cpu.start();
    this.memory.load();
    this.hardDrive.read();
  }
}
```

#### Proxy
```typescript
export interface Image {
  display(): void;
}

export class RealImage implements Image {
  constructor(private filename: string) {
    this.loadFromDisk();
  }
  private loadFromDisk(): void { console.log(`Loading ${this.filename}`); }
  display(): void { console.log(`Displaying ${this.filename}`); }
}

// Proxy
export class ProxyImage implements Image {
  private realImage?: RealImage;
  constructor(private filename: string) {}

  display(): void {
    if (!this.realImage) {
      this.realImage = new RealImage(this.filename);
    }
    this.realImage.display();
  }
}
```

---

### Behavioral Patterns

#### Chain of Responsibility
```typescript
export abstract class Handler {
  protected next?: Handler;
  setNext(handler: Handler): Handler {
    this.next = handler;
    return handler;
  }
  abstract handle(request: string): string | null;
}

export class AuthHandler extends Handler {
  handle(request: string): string | null {
    if (request === 'auth') return 'Authenticated';
    return this.next?.handle(request) || null;
  }
}
```

#### Command (Extended)
```typescript
export interface Command {
  execute(): void;
  undo?(): void;
}

export class AddUserCommand implements Command {
  constructor(
    private receiver: UserService,
    private user: User
  ) {}

  execute(): void { this.receiver.add(this.user); }
  undo(): void { this.receiver.remove(this.user); }
}

// Invoker
export class CommandManager {
  private history: Command[] = [];
  execute(command: Command): void {
    command.execute();
    this.history.push(command);
  }
  undo(): void {
    const cmd = this.history.pop();
    cmd?.undo?.();
  }
}
```

#### Iterator
```typescript
export interface Iterator<T> {
  next(): T | null;
  hasNext(): boolean;
}

export class UserCollection {
  private users: User[] = [];
  getIterator(): Iterator<User> {
    let index = 0;
    return {
      next: () => index < this.users.length ? this.users[index++] : null,
      hasNext: () => index < this.users.length,
    };
  }
}
```

#### Mediator
```typescript
export interface Mediator {
  notify(sender: object, event: string): void;
}

export class ChatRoom implements Mediator {
  private users: User[] = [];
  register(user: User): void { this.users.push(user); }
  notify(sender: User, event: string): void {
    this.users.filter(u => u !== sender).forEach(u => u.receive(sender.name, event));
  }
}
```

#### Memento
```typescript
export class EditorMemento {
  constructor(public readonly content: string, public readonly cursorPos: number) {}
}

export class Editor {
  private content = '';
  private cursorPos = 0;

  type(text: string): void {
    this.content += text;
    this.cursorPos += text.length;
  }

  save(): EditorMemento {
    return new EditorMemento(this.content, this.cursorPos);
  }

  restore(memento: EditorMemento): void {
    this.content = memento.content;
    this.cursorPos = memento.cursorPos;
  }
}
```

#### State
```typescript
export interface State {
  handle(context: Context): void;
}

export class ActiveState implements State {
  handle(context: Context): void {
    console.log('Active: processing');
  }
}

export class InactiveState implements State {
  handle(context: Context): void {
    console.log('Inactive: cannot process');
  }
}

export class Context {
  constructor(private state: State) {}
  setState(state: State): void { this.state = state; }
  request(): void { this.state.handle(this); }
}
```

#### Template Method
```typescript
export abstract class DataImporter {
  import(): void {
    this.connect();
    const data = this.extract();
    this.transform(data);
    this.disconnect();
  }
  protected abstract connect(): void;
  protected abstract extract(): unknown;
  protected abstract transform(data: unknown): void;
  protected abstract disconnect(): void;
}

export class CsvImporter extends DataImporter {
  protected connect(): void { console.log('Opening CSV'); }
  protected extract(): unknown { return 'csv data'; }
  protected transform(data: unknown): void { console.log('Transforming', data); }
  protected disconnect(): void { console.log('Closing CSV'); }
}
```

#### Visitor
```typescript
export interface Visitable {
  accept(visitor: Visitor): void;
}

export interface Visitor {
  visitUser(user: User): void;
  visitOrder(order: Order): void;
}

export class User implements Visitable {
  accept(visitor: Visitor): void { visitor.visitUser(this); }
}

export class Order implements Visitable {
  accept(visitor: Visitor): void { visitor.visitOrder(this); }
}

export class ExportVisitor implements Visitor {
  visitUser(user: User): void { console.log('Exporting user'); }
  visitOrder(order: Order): void { console.log('Exporting order'); }
}
```

