## Enterprise Patterns (DDD)

### Repository (Already covered — extended)
```typescript
// Specification + Repository combo
export class UserRepositoryImpl implements UserRepository {
  async findSatisfying(spec: Specification<User>): Promise<User[]> {
    const all = await this.findAll();
    return all.filter(u => spec.isSatisfiedBy(u));
  }
}
```

### Unit of Work
```typescript
export class UnitOfWork {
  private newEntities: Entity[] = [];
  private dirtyEntities: Entity[] = [];
  private removedEntities: Entity[] = [];

  registerNew(entity: Entity): void { this.newEntities.push(entity); }
  registerDirty(entity: Entity): void { this.dirtyEntities.push(entity); }
  registerRemoved(entity: Entity): void { this.removedEntities.push(entity); }

  async commit(): Promise<void> {
    // Insert new, update dirty, delete removed
    // Single transaction
  }
}
```

### CQRS (Command Query Responsibility Segregation)
```typescript
// Command (writes)
export class CreateUserCommand {
  constructor(public email: string, public password: string) {}
}

export class CreateUserHandler {
  async handle(cmd: CreateUserCommand): Promise<void> {
    // Write to write database
  }
}

// Query (reads)
export class GetUserQuery {
  constructor(public userId: string) {}
}

export class GetUserHandler {
  async handle(query: GetUserQuery): Promise<UserDto> {
    // Read from read database (optimized for reads)
  }
}
```

### Event Sourcing
```typescript
export interface DomainEvent {
  type: string;
  aggregateId: string;
  timestamp: Date;
  payload: unknown;
}

export class UserCreatedEvent implements DomainEvent {
  type = 'USER_CREATED';
  timestamp = new Date();
  constructor(public aggregateId: string, public email: string) {}
}

export class EventStore {
  private events: DomainEvent[] = [];
  append(event: DomainEvent): void { this.events.push(event); }
  getEventsForAggregate(aggregateId: string): DomainEvent[] {
    return this.events.filter(e => e.aggregateId === aggregateId);
  }
}
```

