## 5. Comment Patterns by Layer

### Domain Layer
```typescript
/**
 * Domain entity: User.
 * Encapsulates user state and behavior.
 * No framework dependencies allowed.
 */
export class User {
  /**
   * Business rule: cannot deactivate already inactive user.
   * @throws {BusinessError} if user is already inactive
   */
  deactivate(): void {
    if (!this._isActive) {
      // This invariant is critical: inactive users cannot be deactivated again
      throw new BusinessError('ALREADY_INACTIVE', 'User already inactive');
    }
    this._isActive = false;
  }
}
```

### Application Layer
```typescript
/**
 * Use case: Create a new user.
 * Orchestrates domain creation, persistence, and notifications.
 * Returns Result to avoid throwing for expected business failures.
 */
@Injectable()
export class CreateUserUseCase {
  async execute(dto: CreateUserDto): Promise<Result<User, AppError>> {
    // Check if user already exists (expected failure, return Result.err)
    const existing = await this.repo.findByEmail(dto.email);
    if (existing) {
      return err(new DuplicateUserError(dto.email));
    }

    // Domain creation (pure business logic)
    const email = Email.create(dto.email);
    const user = User.create(dto.id, email, dto.password);

    // Persist (infrastructure call via port)
    await this.repo.save(user);

    // Side effect: notify user (infrastructure call via port)
    await this.notifier.send(dto.email, 'Welcome!', ...);

    return ok(user);
  }
}
```

### Infrastructure Layer
```typescript
/**
 * TypeORM adapter for UserRepository port.
 * Maps between domain User entity and ORM UserOrmEntity.
 */
@Injectable()
export class TypeOrmUserRepository implements UserRepository {
  /**
   * Finds user by ID.
   * Uses TypeORM's findOne with where clause.
   * Returns null if not found (does not throw).
   */
  async findById(id: string): Promise<User | null> {
    // ORM entity lives in infrastructure, domain entity is returned
    const entity = await this.repo.findOne({ where: { id } });
    return entity ? this.toDomain(entity) : null;
  }

  /**
   * Maps ORM entity to domain entity.
   * This method encapsulates the mapping logic to keep repository clean.
   */
  private toDomain(entity: UserOrmEntity): User {
    // Domain factory ensures invariants are maintained during reconstruction
    return User.create(entity.id, Email.create(entity.email), entity.passwordHash);
  }
}
```

---

## 6. Comment Anti-Patterns (Reject)

| ❌ Bad Comment | Why Bad | ✅ Fix |
|---------------|----------|--------|
| `// Add two numbers` | Stating the obvious | Delete comment |
| `// TODO: fix later` | No ticket reference | `// TODO(#123): fix validation` |
| `// @ts-ignore` | No justification | `// HACK: TypeORM bug, see issue #456` |
| `// const old = ...` | Commented code | Delete, use git history |
| `// This is a hack but works` | Not professional | `// HACK: Temporary workaround for...` |
| `// User class` | Redundant | Delete comment |

---

## 7. Magic Numbers/Strings — Use Constants

### Bad (No Comment Needed If Constant Used)
```typescript
// ❌ Magic number
if (user.age > 18) { ... }

// ❌ Magic string
if (user.role === 'admin') { ... }
```

### Good (Self-Documenting Constants)
```typescript
// ✅ Constants are self-documenting, no comment needed
const ADULT_AGE = 18;
if (user.age > ADULT_AGE) { ... }

const ROLE_ADMIN = 'admin';
if (user.role === ROLE_ADMIN) { ... }
```

