## Health & Readiness Endpoints
```typescript
// src/infrastructure/http/controllers/health.controller.ts
import { Controller, Get, Dependencies } from '@nestjs/common';
import { DataSource } from 'typeorm';

@Controller('health')
export class HealthController {
  constructor(
    private dataSource: DataSource,
    @Inject('RedisClient') private redis?: any
  ) {}

  @Get()
  health() {
    return { status: 'healthy', timestamp: new Date().toISOString() };
  }

  @Get('ready')
  async ready() {
    const checks: Record<string, string> = {};

    try {
      await this.dataSource.query('SELECT 1');
      checks.database = 'ok';
    } catch {
      checks.database = 'error';
    }

    if (this.redis) {
      try {
        await this.redis.ping();
        checks.redis = 'ok';
      } catch {
        checks.redis = 'error';
      }
    }

    const healthy = Object.values(checks).every(s => s === 'ok');
    return {
      status: healthy ? 'ready' : 'not_ready',
      checks,
    };
  }
}
```

## Structured JSON Logs (Global Interceptor)
```typescript
// src/infrastructure/logging/logging.interceptor.ts
import { Injectable, NestInterceptor, ExecutionContext, CallHandler } from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const req = context.switchToHttp().getRequest();
    const now = Date.now();

    return next.handle().pipe(
      tap(() => {
        const logEntry = JSON.stringify({
          timestamp: new Date().toISOString(),
          method: req.method,
          url: req.url,
          duration: Date.now() - now,
          traceId: req.traceId,
        });
        console.log(logEntry);
      })
    );
  }
}
```

