## Authentication Port

```typescript
// src/application/ports/auth.service.ts
export interface AuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(userId: string, roles: string[]): string;
  verifyToken(token: string): { userId: string; roles: string[] } | null;
}

// Infrastructure adapter
export class JwtAuthService implements AuthService {
  constructor(private secret: string) {}

  generateToken(userId: string, roles: string[]): string {
    return jwt.sign({ userId, roles }, this.secret, { expiresIn: '1h' });
  }

  verifyToken(token: string): { userId: string; roles: string[] } | null {
    try {
      return jwt.verify(token, this.secret) as { userId: string; roles: string[] };
    } catch {
      return null;
    }
  }
}
```

## Authorization Middleware

```typescript
export function requireRole(allowedRoles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const userRoles = req.user?.roles || [];
    const hasRole = allowedRoles.some(r => userRoles.includes(r));
    if (!hasRole) return res.status(403).json({ error: 'Forbidden' });
    next();
  };
}

// Usage
app.post('/admin/users', requireRole(['admin']), createUserHandler);
```

