# Cross-boundary contracts catalog

The full set of generic types every project in this pack uses to move
data across process and layer boundaries. Place them in
`src/shared/contracts/` and re-export through a barrel.

## `ApiResponse<T>`

The single envelope shape every HTTP endpoint returns.

```ts
export type ApiResponse<T> =
  | { success: true; data: T; meta: ResponseMeta }
  | { success: false; error: ApiError; meta: ResponseMeta };

export interface ResponseMeta {
  readonly requestId: string;
  readonly timestamp: string;       // ISO-8601
  readonly pagination?: PaginationMeta;
}

export interface ApiError {
  readonly code: string;            // 'USER_NOT_FOUND'
  readonly message: string;         // safe to show
  readonly details?: unknown;       // structured, optional
}
```

### Why a discriminated union?

`success: true | false` lets the consumer narrow without `try/catch`:

```ts
const res: ApiResponse<UserDto> = await client.getUser(id);
if (res.success) {
  // res.data is UserDto here
} else {
  // res.error is ApiError here
}
```

### Helpers

```ts
export const ApiResponse = {
  ok<T>(data: T, meta: ResponseMeta): ApiResponse<T> {
    return { success: true, data, meta };
  },
  fail(error: ApiError, meta: ResponseMeta): ApiResponse<never> {
    return { success: false, error, meta };
  },
};
```

## `Paginated<T>`

```ts
export interface PaginationMeta {
  readonly page: number;       // 1-based
  readonly pageSize: number;
  readonly total: number;
  readonly totalPages: number;
  readonly hasNext: boolean;
  readonly hasPrev: boolean;
}

export interface Paginated<T> {
  readonly items: readonly T[];
  readonly pagination: PaginationMeta;
}

export const Paginated = {
  of<T>(items: readonly T[], page: number, pageSize: number, total: number): Paginated<T> {
    const totalPages = Math.max(1, Math.ceil(total / pageSize));
    return {
      items,
      pagination: {
        page,
        pageSize,
        total,
        totalPages,
        hasNext: page < totalPages,
        hasPrev: page > 1,
      },
    };
  },
};
```

### Cursor-based variant

For high-throughput feeds, prefer cursor pagination:

```ts
export interface CursorPage<T> {
  readonly items: readonly T[];
  readonly nextCursor: string | null;
  readonly prevCursor: string | null;
}
```

## `Result<T, E>`

```ts
export type Result<T, E> =
  | { ok: true;  value: T }
  | { ok: false; error: E };

export const Result = {
  ok<T>(value: T): Result<T, never> {
    return { ok: true, value };
  },
  err<E>(error: E): Result<never, E> {
    return { ok: false, error };
  },
  isOk<T, E>(r: Result<T, E>): r is { ok: true; value: T } {
    return r.ok;
  },
  map<T, U, E>(r: Result<T, E>, f: (v: T) => U): Result<U, E> {
    return r.ok ? Result.ok(f(r.value)) : r;
  },
  async mapAsync<T, U, E>(r: Result<T, E>, f: (v: T) => Promise<U>): Promise<Result<U, E>> {
    return r.ok ? Result.ok(await f(r.value)) : r;
  },
  flatMap<T, U, E>(r: Result<T, E>, f: (v: T) => Result<U, E>): Result<U, E> {
    return r.ok ? f(r.value) : r;
  },
};
```

## `Repository<T, ID>`

```ts
export interface Repository<TEntity, TId> {
  findById(id: TId): Promise<TEntity | null>;
  save(entity: TEntity): Promise<void>;
  delete(id: TId): Promise<void>;
}

export interface QueryableRepository<TEntity, TId, TQuery>
  extends Repository<TEntity, TId> {
  find(query: TQuery): Promise<Paginated<TEntity>>;
}
```

## `UseCase<TInput, TOutput>`

```ts
export interface UseCase<TInput, TOutput> {
  execute(input: TInput): Promise<TOutput>;
}
```

## `Clock`, `IdGenerator`, `Random`

Determinism ports — never call `Date.now()`/`Math.random()` directly.

```ts
export interface Clock { now(): Date; }
export interface IdGenerator { next(): string; }
export interface Random {
  int(min: number, max: number): number;
  uuid(): string;
}
```

## `EventBus<E extends DomainEvent>`

```ts
export interface DomainEvent {
  readonly name: string;
  readonly occurredAt: Date;
}

export interface EventBus {
  publish<E extends DomainEvent>(event: E): Promise<void>;
  subscribe<E extends DomainEvent>(
    name: E['name'],
    handler: (event: E) => Promise<void>,
  ): Subscription;
}

export interface Subscription { unsubscribe(): void; }
```

## OpenAPI shape

When publishing OpenAPI, generate every schema **from the shared
contracts**, not by hand-coding. This guarantees runtime types and
documented schemas never drift.

## Versioning rule

If a contract field is renamed or removed, ship a new envelope version
(URI: `/v2/`). Never break `/v1/` consumers silently.

# Generic Response Patterns — Complete Reference

## ApiResponse<T> Variants

### Success Response
```typescript
const response: ApiResponse<User> = {
  success: true,
  data: user,
  metadata: { timestamp: new Date().toISOString(), traceId: 'abc-123' }
};
```

### Error Response
```typescript
const errorResponse: ApiResponse = {
  success: false,
  error: { code: 'NOT_FOUND', message: 'User not found' }
};
```

### Paginated Response
```typescript
const paginated: ApiResponse<Paginated<User>> = {
  success: true,
  data: {
    items: users,
    total: 100,
    page: 1,
    limit: 10,
    hasMore: true
  }
};
```

## Result<T,E> Patterns

### Success Path
```typescript
const result: Result<User, AppError> = await useCase.execute(id);
if (result.success) {
  console.log(result.value); // User
}
```

### Error Path
```typescript
if (!result.success) {
  console.log(result.error.code); // Error code string
  console.log(result.error.message); // Error message
}
```

### Chaining Results (Helper)
```typescript
export const mapResult = <T, U, E extends AppError>(
  result: Result<T, E>,
  fn: (value: T) => U
): Result<U, E> => result.success ? ok(fn(result.value)) : result;

// Usage
const userResult = await getUser(id);
const nameResult = mapResult(userResult, user => user.name);
```

## Repository<T,ID> Implementations

### Domain Port (Interface)
```typescript
// src/application/ports/user.repository.ts
export interface UserRepository extends Repository<User, string> {
  findByEmail(email: string): Promise<User | null>;
}
```

### Infrastructure Adapter
```typescript
// src/infrastructure/repositories/typeorm-user.repository.ts
export class TypeOrmUserRepository implements UserRepository {
  constructor(private ormRepo: Repository<UserOrmEntity>) {}

  async findById(id: string): Promise<User | null> {
    const entity = await this.ormRepo.findOne({ where: { id } });
    return entity ? this.toDomain(entity) : null;
  }

  async save(user: User): Promise<User> {
    const ormEntity = this.toOrm(user);
    await this.ormRepo.save(ormEntity);
    return user;
  }

  async findByEmail(email: string): Promise<User | null> {
    const entity = await this.ormRepo.findOne({ where: { email } });
    return entity ? this.toDomain(entity) : null;
  }
}
```

## Paginated<T> Usage
```typescript
export interface Paginated<T> {
  readonly items: readonly T[];
  readonly total: number;
  readonly page: number;
  readonly limit: number;
  readonly hasMore: boolean;
}

// In use-case
const [items, total] = await this.repo.findPage(page, limit);
return ok({ items, total, page, limit, hasMore: page * limit < total });
